import { useResults } from "../context/ResultsContext";
import { useNavigate } from "react-router-dom";

export default function Results() {
  const { results } = useResults();
  const navigate = useNavigate();

  if (!results || results.length === 0) {
    return (
      <div className="page-wrapper">
        <div className="container-fluid px-5">
          <p>No results yet</p>
        </div>
      </div>
    );
  }

  const getBadgeClass = (decision) => {
    if (decision === "Shortlisted") return "badge badge-shortlisted";
    if (decision === "Rejected") return "badge badge-rejected";
    return "badge badge-review";
  };

  return (
    <div className="page-wrapper">
      <div className="container-fluid px-5">
        <h2 className="page-title">Screening Results</h2>
        <p className="page-subtitle">JD‑aware resume screening outcomes</p>

        <div className="theme-card">
          {results.map((r, i) => (
            <div
              key={i}
              className="result-item"
              onClick={() => navigate(`/candidate/${i}`)}
              style={{ cursor: "pointer" }}
            >
              <div className="d-flex justify-content-between align-items-center">
                <h5>{r.filename}</h5>
                <span className={getBadgeClass(r.decision)}>{r.decision}</span>
              </div>

              <div className="mt-2 text-muted">
                Match Score: {r.final_score}%
              </div>

              <div className="mt-3">
                <strong>Strengths</strong>
                <ul>
                  {r.ai?.strengths?.map((s, idx) => (
                    <li key={idx}>{s}</li>
                  ))}
                </ul>
              </div>

              <div className="mt-2">
                <strong>Red Flags</strong>
                <ul>
                  {r.ai?.red_flags?.map((rf, idx) => (
                    <li key={idx}>{rf}</li>
                  ))}
                </ul>
              </div>

              <hr />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
